    p = ::omnibuf::write_const_varint_raw<33ULL>(p);
    p = ::omnibuf::write_varint_raw(p, ::omnibuf::encode_zigzag(static_cast<int64_t>(this->f_int32)));
    p = ::omnibuf::write_const_varint_raw<49ULL>(p);
    p = ::omnibuf::write_varint_raw(p, ::omnibuf::encode_zigzag(static_cast<int64_t>(this->f_int64)));
    p = ::omnibuf::write_const_varint_raw<73ULL>(p);
    ::omnibuf::write_u64_le(p, ::omnibuf::float64_to_bits(this->f_float64));
