inline const char* BatchMessage::try_marshal_omnibuf_fast(::omnibuf::FastWriter& w, int depth, bool check_large) const {
  (void)w;
  (void)check_large;
  if (depth > ::omnibuf::MAX_CONTAINER_DEPTH) [[unlikely]] {
    return "omnibuf: max nesting depth exceeded";
  }
  {
    if ((depth) + 1 > ::omnibuf::MAX_CONTAINER_DEPTH) [[unlikely]] {
      return "omnibuf: max nesting depth exceeded";
    }
    w.write_tag_const<1u, ::omnibuf::WireArray>();
    if (!(check_large)) [[likely]] {
      const size_t len_pos = w.reserve_len_2b();
      w.write_byte(::omnibuf::WireSubMsg);
      w.write_varint(this->items.size());
      for (const auto& elem : this->items) {
        if (const char* err = elem.try_marshal_omnibuf_submsg_fast(w, (depth) + 2)) [[unlikely]] return err;
      }
      w.backpatch_len(len_pos);
    } else {
      size_t arr_hint = 2u;
      for (const auto& elem : this->items) {
        const size_t eh = elem.min_wire_size((depth) + 2);
        arr_hint += (eh > 16383u ? 4u : 2u) + eh;
        if (arr_hint > 16383u) break;
      }
      const bool arr_4b = arr_hint > 16383u;
      const size_t len_pos = w.reserve_len_hint(arr_hint);
      w.write_byte(::omnibuf::WireSubMsg);
      w.write_varint(this->items.size());
      for (const auto& elem : this->items) {
        const size_t elem_hint = arr_4b ? elem.min_wire_size((depth) + 2) : 0u;
        const bool elem_4b = elem_hint > 16383u;
        const size_t elem_pos = w.reserve_len_hint(elem_hint);
        if (const char* err = elem.try_marshal_omnibuf_fast(w, (depth) + 2, elem_4b)) [[unlikely]] return err;
        w.backpatch_len_hint(elem_pos, elem_4b);
      }
      w.backpatch_len_hint(len_pos, arr_4b);
    }
  }
  return nullptr;
}

inline const char* BatchMessage::try_marshal_omnibuf_submsg_fast(::omnibuf::FastWriter& w, int depth) const {
  const size_t len_pos = w.reserve_len_2b();
  if (const char* err = try_marshal_omnibuf_fast(w, depth, false)) [[unlikely]] return err;
  w.backpatch_len(len_pos);
  return nullptr;
}

