inline std::shared_ptr<::omnibuf::SchemaMeta> BatchDocument::schema_meta(int schema_depth, std::set<const void*>& active, bool* cyclic) {
  static const int kTypeToken = 0;
  if (schema_depth + 1 > ::omnibuf::MAX_CONTAINER_DEPTH) {
    return nullptr;
  }
  if (active.contains(&kTypeToken)) {
    if (cyclic != nullptr) *cyclic = true;
    return nullptr;
  }
  active.insert(&kTypeToken);
  auto meta = std::make_shared<::omnibuf::SchemaMeta>();
  meta->type_name = "BatchDocument";
  meta->fields[1u] = "items";
  if (schema_depth + 3 <= ::omnibuf::MAX_CONTAINER_DEPTH) {
    if (auto c = ::omnibuf_bench::v2::Document::schema_meta(schema_depth + 2, active, cyclic)) meta->children[1u] = std::move(c);
  }
  active.erase(&kTypeToken);
  return meta;
}

inline std::shared_ptr<::omnibuf::SchemaMeta> BatchDocument::schema_meta(int schema_depth) {
  std::set<const void*> active;
  return schema_meta(schema_depth, active, nullptr);
}

inline std::shared_ptr<::omnibuf::SchemaMeta> BatchDocument::value_schema_meta(int schema_depth) const {
  if (schema_depth + 1 > ::omnibuf::MAX_CONTAINER_DEPTH) return nullptr;
  auto meta = std::make_shared<::omnibuf::SchemaMeta>();
  meta->type_name = "BatchDocument";
  meta->fields[1u] = "items";
  if (schema_depth + 3 <= ::omnibuf::MAX_CONTAINER_DEPTH) {
    std::shared_ptr<::omnibuf::SchemaMeta> child;
    for (const auto& elem : this->items) {
      child = ::omnibuf::merge_schema_meta(child, elem.value_schema_meta(schema_depth + 2));
    }
    if (child) meta->children[1u] = std::move(child);
  }
  return meta;
}

inline size_t BatchDocument::min_wire_size(int depth) const noexcept {
  if (depth > ::omnibuf::MAX_CONTAINER_DEPTH) return 0u;
  size_t sz = 0u;
  sz += 5u;
  for (const auto& elem : this->items) {
    sz += 2u + elem.min_wire_size(depth + 2);
  }
  return sz;
}

