    p = ::omnibuf::write_varint_raw(p, ::omnibuf::encode_zigzag(static_cast<int64_t>(this->price_minor)));
    const size_t body_len = static_cast<size_t>(p - (start + 2));
    ::omnibuf::write_u16_le(start, static_cast<uint16_t>((body_len << 2) | 2u));
    w.set_raw_cur(p);
