inline const char* BatchNestedRow::decode_omnibuf_raw(std::span<const uint8_t> data, int depth, bool merge, bool is_fresh, ::omnibuf::DecodeState& state) {
  if (!merge && !is_fresh) {
    return decode_omnibuf_impl<true>(data, depth, merge, state);
  }
  return decode_omnibuf_impl<false>(data, depth, merge, state);
}

template <bool ClearUnseen>
inline const char* BatchNestedRow::decode_omnibuf_impl(std::span<const uint8_t> data, int depth, bool merge, ::omnibuf::DecodeState& state) {
  if (depth > state.opts.max_depth) [[unlikely]] {
    return "omnibuf: max nesting depth exceeded";
  }
  (void)merge;
  std::array<uint64_t, 1> seen_words{};
  (void)seen_words;
  const size_t n = data.size();
  const uint8_t* base = data.data();
  size_t pos = 0;
  while (pos < n) {
    uint64_t tag = 0;
    const uint8_t b0 = base[pos];
    if ((b0 & 1u) != 0) [[likely]] {
      tag = static_cast<uint64_t>(b0 >> 1);
      ++pos;
    } else if ((b0 & 2u) != 0 && pos + 2 <= n) {
      tag = static_cast<uint64_t>(::omnibuf::read_u16_le(base + pos) >> 2);
      pos += 2;
    } else {
      const auto [t64, tn] = ::omnibuf::decode_varint(data.subspan(pos));
      if (tn == 0 || (t64 >> 4) > ::omnibuf::MAX_FIELD_NUMBER) [[unlikely]] {
        return "omnibuf: invalid tag";
      }
      tag = t64;
      pos += tn;
    }
    switch (tag) {
      case ::omnibuf::WireSubMsg: {
        auto f0 = ::omnibuf::validate_field0(data, pos, ::omnibuf::WireSubMsg, depth, state);
        if (!f0) return "omnibuf: invalid Field #0";
        pos = f0.value();
        break;
      }
      case 29ULL: {
        if (depth + 1 > state.opts.max_depth) [[unlikely]] {
          return "omnibuf: max nesting depth exceeded";
        }
        const auto ar = ::omnibuf::read_len_slice_fast(data, pos, 2);
        if (!ar) [[unlikely]] return ar.err;
        const auto body = ar.span();
        const auto hdr = ::omnibuf::parse_array_header(body);
        if (!hdr.ok || hdr.elem_wt != ::omnibuf::WireSubMsg) [[unlikely]] {
          return "omnibuf: invalid submsg array header";
        }
        if (!state.charge_elements(hdr.count)) [[unlikely]] {
          return "omnibuf: max decoded elements exceeded";
        }
        if constexpr (ClearUnseen) {
          if ((seen_words[0] & 1ULL) == 0) {
            this->items.clear();
          }
          seen_words[0] |= 1ULL;
        }
        size_t p = hdr.pos;
        if (hdr.count <= 64u) [[likely]] {
          const size_t old_sz = this->items.size();
          this->items.resize(old_sz + hdr.count);
          auto* out_elems = this->items.data() + old_sz;
          for (size_t i = 0; i < hdr.count; ++i) {
            const auto es = ::omnibuf::read_len_slice_fast(body, p, 0);
            if (!es) [[unlikely]] return es.err;
            const char* dr = out_elems[i].template decode_omnibuf_impl<false>(es.span(), depth + 2, false, state);
            if (dr != nullptr) [[unlikely]] return dr;
            p = es.next_pos;
          }
        } else {
          this->items.reserve(::omnibuf::bounded_reserve_target(this->items.capacity(), this->items.size(), hdr.count));
          for (size_t i = 0; i < hdr.count; ++i) {
            const auto es = ::omnibuf::read_len_slice_fast(body, p, 0);
            if (!es) [[unlikely]] return es.err;
            auto& elem = this->items.emplace_back();
            const char* dr = elem.template decode_omnibuf_impl<false>(es.span(), depth + 2, false, state);
            if (dr != nullptr) [[unlikely]] return dr;
            p = es.next_pos;
          }
        }
        if (p != body.size()) [[unlikely]] {
          return "omnibuf: trailing bytes in submsg array";
        }
        pos = ar.next_pos;
        break;
      }
      default: {
        const uint32_t fnum = static_cast<uint32_t>(tag >> 4);
        const uint8_t wt = static_cast<uint8_t>(tag & 0x0Fu);
        if (fnum == 0) [[unlikely]] {
          return "omnibuf: invalid field number 0";
        }
        auto sk = ::omnibuf::validate_value(data, pos, wt, depth, state);
        if (!sk) [[unlikely]] return "omnibuf: invalid unknown field";
        pos = sk.value();
        break;
      }
    }
  }
  if constexpr (ClearUnseen) {
  if ((seen_words[0] & 1ULL) != 1ULL) {
    if ((seen_words[0] & 1ULL) == 0) {
      this->items.clear();
    }
  }
  }
  return nullptr;
}

