inline const char* SignalLeg::try_marshal_omnibuf_fast(::omnibuf::FastWriter& w, int depth, bool check_large) const {
  (void)w;
  (void)check_large;
  if (depth > ::omnibuf::MAX_CONTAINER_DEPTH) [[unlikely]] {
    return "omnibuf: max nesting depth exceeded";
  }
  size_t max_bytes = 30u;
  if (max_bytes <= 512u) [[likely]] {
    w.ensure(max_bytes);
    uint8_t* p = w.raw_cur();
    p = ::omnibuf::write_const_varint_raw<17ULL>(p);
    p = ::omnibuf::write_varint_raw(p, ::omnibuf::encode_zigzag(static_cast<int64_t>(this->leg_id)));
    p = ::omnibuf::write_const_varint_raw<33ULL>(p);
    p = ::omnibuf::write_varint_raw(p, ::omnibuf::encode_zigzag(static_cast<int64_t>(this->leg_qty)));
    p = ::omnibuf::write_const_varint_raw<49ULL>(p);
    p = ::omnibuf::write_varint_raw(p, ::omnibuf::encode_zigzag(static_cast<int64_t>(this->leg_pad)));
    w.set_raw_cur(p);
    return nullptr;
  }
  w.write_tagged_varint<1u, ::omnibuf::WireSint>(::omnibuf::encode_zigzag(static_cast<int64_t>(this->leg_id)));
  w.write_tagged_varint<2u, ::omnibuf::WireSint>(::omnibuf::encode_zigzag(static_cast<int64_t>(this->leg_qty)));
  w.write_tagged_varint<3u, ::omnibuf::WireSint>(::omnibuf::encode_zigzag(static_cast<int64_t>(this->leg_pad)));
  return nullptr;
}

inline const char* SignalLeg::try_marshal_omnibuf_submsg_fast(::omnibuf::FastWriter& w, int depth) const {
  if (depth > ::omnibuf::MAX_CONTAINER_DEPTH) [[unlikely]] {
    return "omnibuf: max nesting depth exceeded";
  }
  size_t max_bytes = 30u;
  if (max_bytes <= 512u) [[likely]] {
    w.ensure(2u + max_bytes);
    uint8_t* const start = w.raw_cur();
    uint8_t* p = start + 2;
    p = ::omnibuf::write_const_varint_raw<17ULL>(p);
    p = ::omnibuf::write_varint_raw(p, ::omnibuf::encode_zigzag(static_cast<int64_t>(this->leg_id)));
    p = ::omnibuf::write_const_varint_raw<33ULL>(p);
    p = ::omnibuf::write_varint_raw(p, ::omnibuf::encode_zigzag(static_cast<int64_t>(this->leg_qty)));
    p = ::omnibuf::write_const_varint_raw<49ULL>(p);
    p = ::omnibuf::write_varint_raw(p, ::omnibuf::encode_zigzag(static_cast<int64_t>(this->leg_pad)));
    const size_t body_len = static_cast<size_t>(p - (start + 2));
    ::omnibuf::write_u16_le(start, static_cast<uint16_t>((body_len << 2) | 2u));
    w.set_raw_cur(p);
    return nullptr;
  }
  const size_t len_pos = w.reserve_len_2b();
  if (const char* err = try_marshal_omnibuf_fast(w, depth, false)) [[unlikely]] return err;
  w.backpatch_len(len_pos);
  return nullptr;
}

