  const size_t pad = (root_hint <= SIZE_MAX - 512u) ? (root_hint + 512u) : root_hint;
  ::omnibuf::FastWriter w(dst, pad);
  if (const char* err = try_marshal_omnibuf_fast(w, 0, true)) [[unlikely]] {
    return ::omnibuf::Error{err};
  }
